<template>
    <div class="id-card-upload">
      <h2>请拍摄身份证正反面</h2>
      <div class="camera-area">
        <video ref="video" autoplay playsinline v-if="isCameraOn"></video>
        <canvas ref="canvas" style="display: none;"></canvas>
        <img src="https://img.alicdn.com/tfs/TB1G9ZsXhv1gK0jSZFFXXb0sXXa-512-512.png" alt="国徽" class="national-emblem" />
        <p>请将身份证放入框内，并对准国徽位置</p>
      </div>
      <button @click="toggleCamera">{{ isCameraOn ? '关闭摄像头' : '打开摄像头' }}</button>
      <button @click="capture" :disabled="!isCameraOn">拍照</button>
      <div v-if="capturedImage" class="preview">
        <h3>已拍摄的照片：</h3>
        <img :src="capturedImage" alt="身份证照片" class="captured-image" />
      </div>
    </div>
  </template>
  
  <script>
  export default {
    data() {
      return {
        isCameraOn: false,
        capturedImage: null,
        videoStream: null,
      };
    },
    methods: {
      async toggleCamera() {
        if (this.isCameraOn) {
          // 关闭摄像头
          this.isCameraOn = false;
          if (this.videoStream) {
            const tracks = this.videoStream.getTracks();
            tracks.forEach(track => track.stop());
          }
        } else {
          // 打开摄像头
          try {
            this.isCameraOn = true; // 确保 video 元素被渲染
            await this.$nextTick(); // 等待 DOM 更新完成
  
            this.videoStream = await navigator.mediaDevices.getUserMedia({
            //   video: { facingMode: "environment" } // 使用后置摄像头
              video: { facingMode: "user" } // 使用前置摄像头
            });
  
            // 确保 video 元素存在
            if (this.$refs.video) {
              this.$refs.video.srcObject = this.videoStream;
            } else {
              throw new Error("Video element not found!");
            }
          } catch (error) {
            alert("无法访问摄像头，请确保已授予摄像头权限。");
            console.error("摄像头访问失败:", error);
          }
        }
      },
      capture() {
        if (!this.isCameraOn) return;
  
        const video = this.$refs.video;
        const canvas = this.$refs.canvas;
        const context = canvas.getContext('2d');
  
        // 设置画布大小与视频一致
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
  
        // 将视频帧绘制到画布上
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
  
        // 获取画布上的图像数据并转换为图片URL
        this.capturedImage = canvas.toDataURL('image/png');
      },
    },
  };
  </script>
  
  <style scoped>
  .id-card-upload {
    text-align: center;
    margin-top: 50px;
  }
  
  .camera-area {
    position: relative;
    width: 300px;
    height: 200px;
    border: 2px dashed #ccc;
    margin: 20px auto;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    background-color: #f9f9f9;
  }
  
  .national-emblem {
    width: 50px;
    height: 50px;
  }
  
  .camera-area p {
    margin-top: 10px;
    font-size: 14px;
    color: #666;
  }
  
  video {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
  
  button {
    padding: 10px 20px;
    font-size: 16px;
    background-color: #42b983;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    margin: 10px;
  }
  
  button:disabled {
    background-color: #ccc;
  }
  
  .preview {
    margin-top: 20px;
  }
  
  .captured-image {
    max-width: 100%;
    height: auto;
    margin-top: 10px;
  }
  </style>
  